5. Crack eggs between the tomatoes and season with salt and pepper.
6. Reduce heat, cover and cook for 4вЂ“6 minutes until whites and yolks are set.
7. Sprinkle with chopped parsley.','/images/recipes/fried-eggs-tomatoes.webp'),
('РћР»Р°РґРєРё','Kefir pancakes','РџСѓС…РєС– РѕР»Р°РґРєРё РЅР° РєРµС„С–СЂС–.','Fluffy kefir pancakes.',25,590,2,'1. Р—РјС–С€Р°Р№С‚Рµ РєРµС„С–СЂ РєС–РјРЅР°С‚РЅРѕС— С‚РµРјРїРµСЂР°С‚СѓСЂРё Р· СЏР№С†РµРј, С†СѓРєСЂРѕРј С– СЃС–Р»Р»СЋ.
2. РћРєСЂРµРјРѕ Р·РјС–С€Р°Р№С‚Рµ Р±РѕСЂРѕС€РЅРѕ С‚Р° СЃРѕРґСѓ.
3. РџРѕСЃС‚СѓРїРѕРІРѕ РґРѕРґР°Р№С‚Рµ СЃСѓС…Сѓ СЃСѓРјС–С€ РґРѕ РєРµС„С–СЂСѓ, РїРµСЂРµРјС–С€Р°Р№С‚Рµ РґРѕ РіСѓСЃС‚РѕРіРѕ С‚С–СЃС‚Р°.
4. Р—Р°Р»РёС€С‚Рµ РЅР° 5 С…РІРёР»РёРЅ.
5. Р РѕР·С–РіСЂС–Р№С‚Рµ РѕР»С–СЋ РЅР° СЃРµСЂРµРґРЅСЊРѕРјСѓ РІРѕРіРЅС–.
6. Р’РёРєР»Р°РґР°Р№С‚Рµ С‚С–СЃС‚Рѕ СЃС‚РѕР»РѕРІРѕСЋ Р»РѕР¶РєРѕСЋ, Р·Р°Р»РёС€Р°СЋС‡Рё РїСЂРѕРјС–Р¶РєРё.
7. РЎРјР°Р¶С‚Рµ РїРѕ 2вЂ“3 С…РІРёР»РёРЅРё Р· РєРѕР¶РЅРѕРіРѕ Р±РѕРєСѓ РґРѕ РіРѕС‚РѕРІРЅРѕСЃС‚С– СЃРµСЂРµРґРёРЅРё.
8. РџРѕРґР°РІР°Р№С‚Рµ Р· Р№РѕРіСѓСЂС‚РѕРј, СЏРіРѕРґР°РјРё, РїСѓРґСЂРѕСЋ С‚Р° РјвЂ™СЏС‚РѕСЋ.','1. Mix room-temperature kefir with egg, sugar and salt.
2. Combine flour and baking soda separately.
3. Gradually stir dry ingredients into kefir to form a thick batter.
4. Rest for 5 minutes.
5. Heat oil over medium heat.
6. Spoon batter into the pan, leaving space between pancakes.
7. Fry for 2вЂ“3 minutes per side until cooked through.
8. Serve with yogurt, berries, powdered sugar and mint.','/images/recipes/kefir-pancakes.webp'),
('РўРѕСЃС‚Рё Р· Р°РІРѕРєР°РґРѕ','Avocado toast','РҐСЂСѓСЃС‚РєС– С‚РѕСЃС‚Рё Р· Р°РІРѕРєР°РґРѕ С‚Р° Р»РёРјРѕРЅРѕРј.','Crisp toast with avocado and lemon.',15,410,1,'1. РџС–РґСЃСѓС€С–С‚СЊ С…Р»С–Р± РЅР° СЃСѓС…С–Р№ РїР°С‚РµР»СЊРЅС– РїРѕ 1вЂ“2 С…РІРёР»РёРЅРё Р· РєРѕР¶РЅРѕРіРѕ Р±РѕРєСѓ.
2. Р РѕР·СЂС–Р¶С‚Рµ Р°РІРѕРєР°РґРѕ, РІРёРґР°Р»С–С‚СЊ РєС–СЃС‚РѕС‡РєСѓ С‚Р° С€РєС–СЂРєСѓ.
3. Р РѕР·С–РјРЅС–С‚СЊ РїРѕР»РѕРІРёРЅСѓ РјвЂ™СЏРєРѕС‚С– Р· Р»РёРјРѕРЅРЅРёРј СЃРѕРєРѕРј, СЃС–Р»Р»СЋ С‚Р° РїРµСЂС†РµРј, СЂРµС€С‚Сѓ РЅР°СЂС–Р¶С‚Рµ СЃРєРёР±РєР°РјРё.
4. Р”РѕРІРµРґС–С‚СЊ РІРѕРґСѓ РґРѕ СЃР»Р°Р±РєРѕРіРѕ РєРёРїС–РЅРЅСЏ.
5. Р РѕР·Р±РёР№С‚Рµ СЏР№С†Рµ РІ С‡Р°С€РєСѓ, РѕР±РµСЂРµР¶РЅРѕ РѕРїСѓСЃС‚С–С‚СЊ Сѓ РІРѕРґСѓ С‚Р° РІР°СЂС–С‚СЊ 4вЂ“5 С…РІРёР»РёРЅ Р°Р±Рѕ РґРѕРІС€Рµ РґРѕ Р±Р°Р¶Р°РЅРѕС— РіРѕС‚РѕРІРЅРѕСЃС‚С–; РґР»СЏ РїРѕРІРЅРѕС— РіРѕС‚РѕРІРЅРѕСЃС‚С– Р¶РѕРІС‚РѕРє РјР°С” Р·Р°СЃС‚РёРіРЅСѓС‚Рё.
6. РќР°РјР°СЃС‚С–С‚СЊ С…Р»С–Р± Р°РІРѕРєР°РґРѕ, РІРёРєР»Р°РґС–С‚СЊ СЃРєРёР±РєРё С‚Р° СЏР№С†Рµ.
7. РџРѕСЃРёРїС‚Рµ РїР°РїСЂРёРєРѕСЋ С‚Р° РїРµС‚СЂСѓС€РєРѕСЋ.','1. Toast bread in a dry pan for 1вЂ“2 minutes per side.
2. Halve avocado and remove pit and skin.
3. Mash half with lemon juice, salt and pepper; slice the rest.
4. Bring water to a gentle simmer.
5. Crack egg into a cup, slide into water and poach for 4вЂ“5 minutes or longer to desired doneness; for fully cooked eggs the yolk should be firm.
6. Spread avocado on toast and add slices and egg.
7. Sprinkle with paprika and parsley.','/images/recipes/avocado-toast.webp')
) AS v(uk,en,d,de,t,k,s,i,ie,image)
