    SELECT v.uk, v.en, v.d, v.de, c."Id",
           v.t, v.k, v.s, v.i, v.ie, ''
    FROM (VALUES
    (
        'РЈРєСЂР°С—РЅСЃСЊРєРёР№ Р±РѕСЂС‰',
        'Ukrainian borscht',
        'РўСЂР°РґРёС†С–Р№РЅРёР№ СѓРєСЂР°С—РЅСЃСЊРєРёР№ Р±РѕСЂС‰ С–Р· СЏР»РѕРІРёС‡РёРЅРѕСЋ, Р±СѓСЂСЏРєРѕРј, РєР°РїСѓСЃС‚РѕСЋ С‚Р° СЃРјРµС‚Р°РЅРѕСЋ.',
        'Traditional Ukrainian borscht with beef, beetroot, cabbage and sour cream.',
        100, 380, 4,
        '1. РџСЂРѕРјРёР№С‚Рµ СЏР»РѕРІРёС‡РёРЅСѓ, РїРѕРєР»Р°РґС–С‚СЊ Сѓ РєР°СЃС‚СЂСѓР»СЋ С‚Р° Р·Р°Р»РёР№С‚Рµ РІРѕРґРѕСЋ.
    2. Р”РѕРІРµРґС–С‚СЊ РґРѕ РєРёРїС–РЅРЅСЏ, Р·РЅС–РјС–С‚СЊ РїС–РЅСѓ С‚Р° РІР°СЂС–С‚СЊ РЅР° СЃР»Р°Р±РєРѕРјСѓ РІРѕРіРЅС– РїСЂРёР±Р»РёР·РЅРѕ 45 С…РІРёР»РёРЅ.
    3. РћС‡РёСЃС‚СЊС‚Рµ РєР°СЂС‚РѕРїР»СЋ, Р±СѓСЂСЏРє, РјРѕСЂРєРІСѓ, С†РёР±СѓР»СЋ С‚Р° С‡Р°СЃРЅРёРє.
    4. РќР°СЂС–Р¶С‚Рµ РєР°СЂС‚РѕРїР»СЋ РєСѓР±РёРєР°РјРё, РєР°РїСѓСЃС‚Сѓ С‚РѕРЅРєРёРјРё СЃРјСѓР¶РєР°РјРё, С†РёР±СѓР»СЋ РґСЂС–Р±РЅРёРјРё РєСѓР±РёРєР°РјРё. РќР°С‚СЂС–С‚СЊ РјРѕСЂРєРІСѓ С‚Р° Р±СѓСЂСЏРє.
    5. Р”РѕРґР°Р№С‚Рµ РєР°СЂС‚РѕРїР»СЋ РґРѕ Р±СѓР»СЊР№РѕРЅСѓ С‚Р° РІР°СЂС–С‚СЊ 10 С…РІРёР»РёРЅ.
    6. Р РѕР·С–РіСЂС–Р№С‚Рµ РѕР»С–СЋ РЅР° РїР°С‚РµР»СЊРЅС–. РћР±СЃРјР°Р¶С‚Рµ С†РёР±СѓР»СЋ С‚Р° РјРѕСЂРєРІСѓ РїСЂРѕС‚СЏРіРѕРј 5 С…РІРёР»РёРЅ.
    7. Р”РѕРґР°Р№С‚Рµ Р±СѓСЂСЏРє, С‚РѕРјР°С‚РЅСѓ РїР°СЃС‚Сѓ, РѕС†РµС‚ С– С†СѓРєРѕСЂ. РўСѓС€РєСѓР№С‚Рµ 10 С…РІРёР»РёРЅ.
    8. Р”РѕРґР°Р№С‚Рµ РєР°РїСѓСЃС‚Сѓ С‚Р° РѕРІРѕС‡РµРІСѓ Р·Р°СЃРјР°Р¶РєСѓ РґРѕ РєР°СЃС‚СЂСѓР»С–.
    9. Р”РѕРґР°Р№С‚Рµ СЃС–Р»СЊ, РїРµСЂРµС†СЊ С– Р»Р°РІСЂРѕРІРёР№ Р»РёСЃС‚. Р’Р°СЂС–С‚СЊ С‰Рµ 15 С…РІРёР»РёРЅ РґРѕ РјвЂ™СЏРєРѕСЃС‚С– РѕРІРѕС‡С–РІ.
    10. Р”РѕРґР°Р№С‚Рµ РїРѕРґСЂС–Р±РЅРµРЅРёР№ С‡Р°СЃРЅРёРє, РІРёРјРєРЅС–С‚СЊ РЅР°РіСЂС–РІР°РЅРЅСЏ С‚Р° Р·Р°Р»РёС€С‚Рµ Р±РѕСЂС‰ РїС–Рґ РєСЂРёС€РєРѕСЋ РЅР° 10 С…РІРёР»РёРЅ.
    11. Р’РёРґР°Р»С–С‚СЊ Р»Р°РІСЂРѕРІРёР№ Р»РёСЃС‚. РџРѕРґР°РІР°Р№С‚Рµ Р·С– СЃРјРµС‚Р°РЅРѕСЋ С‚Р° РїРѕРґСЂС–Р±РЅРµРЅРёРј РєСЂРѕРїРѕРј.',
        '1. Rinse the beef, place it in a pot and cover with water.
    2. Bring to a boil, skim off the foam and simmer for approximately 45 minutes.
    3. Peel the potatoes, beetroot, carrots, onion and garlic.
    4. Dice the potatoes and onion, shred the cabbage and grate the carrots and beetroot.
    5. Add the potatoes to the broth and cook for 10 minutes.
    6. Heat the oil in a frying pan. Fry the onion and carrots for 5 minutes.
    7. Add the beetroot, tomato paste, vinegar and sugar. Cook for 10 minutes.
    8. Add the cabbage and fried vegetables to the pot.
    9. Add salt, pepper and bay leaf. Simmer for another 15 minutes until the vegetables are tender.
    10. Add minced garlic, turn off the heat and leave covered for 10 minutes.
    11. Remove the bay leaf. Serve with sour cream and chopped dill.'
    ),
    (
        'РљСѓСЂСЏС‡РёР№ СЃСѓРї',
        'Chicken soup',
        'Р›РµРіРєРёР№ РґРѕРјР°С€РЅС–Р№ СЃСѓРї С–Р· РєСѓСЂСЏС‡РёРј С„С–Р»Рµ, РєР°СЂС‚РѕРїР»РµСЋ, РјРѕСЂРєРІРѕСЋ С‚Р° РјР°РєР°СЂРѕРЅР°РјРё.',
        'Light homemade soup with chicken breast, potatoes, carrots and pasta.',
        45, 310, 4,
