        'РЎРѕРєРѕРІРёС‚Рµ С„С–Р»Рµ Р»РѕСЃРѕСЃСЏ, Р·Р°РїРµС‡РµРЅРµ Р· Р»РёРјРѕРЅРѕРј, С‡Р°СЃРЅРёРєРѕРј С‚Р° Р°СЂРѕРјР°С‚РЅРёРјРё С‚СЂР°РІР°РјРё.',
        'Juicy salmon fillet baked with lemon, garlic and aromatic herbs.',
        30, 460, 2,
        '1. Р РѕР·С–РіСЂС–Р№С‚Рµ РґСѓС…РѕРІРєСѓ РґРѕ 190 В°C.
    2. РћР±СЃСѓС€С–С‚СЊ С„С–Р»Рµ Р»РѕСЃРѕСЃСЏ РїР°РїРµСЂРѕРІРёРј СЂСѓС€РЅРёРєРѕРј С‚Р° РїРµСЂРµРІС–СЂС‚Рµ, С‡Рё РЅРµРјР°С” РєС–СЃС‚РѕРє.
    3. РћС‡РёСЃС‚СЊС‚Рµ С‡Р°СЃРЅРёРє С– РґСЂС–Р±РЅРѕ РїРѕРґСЂС–Р±РЅС–С‚СЊ Р№РѕРіРѕ.
    4. РџРѕРјРёР№С‚Рµ Р»РёРјРѕРЅ. Р— РїРѕР»РѕРІРёРЅРё Р»РёРјРѕРЅР° РІРёС‡Р°РІС–С‚СЊ СЃС–Рє, СЂРµС€С‚Сѓ РЅР°СЂС–Р¶С‚Рµ С‚РѕРЅРєРёРјРё РєСЂСѓР¶Р°Р»СЊС†СЏРјРё.
    5. Р—РјС–С€Р°Р№С‚Рµ РѕР»РёРІРєРѕРІСѓ РѕР»С–СЋ, Р»РёРјРѕРЅРЅРёР№ СЃС–Рє, С‡Р°СЃРЅРёРє, СЃС–Р»СЊ С– С‡РѕСЂРЅРёР№ РїРµСЂРµС†СЊ.
    6. Р’РёРєР»Р°РґС–С‚СЊ Р»РѕСЃРѕСЃСЊ Сѓ С„РѕСЂРјСѓ РґР»СЏ Р·Р°РїС–РєР°РЅРЅСЏ С€РєС–СЂРєРѕСЋ РґРѕРЅРёР·Сѓ.
    7. РџРѕР»РёР№С‚Рµ СЂРёР±Сѓ РјР°СЂРёРЅР°РґРѕРј С– РІРёРєР»Р°РґС–С‚СЊ Р·РІРµСЂС…Сѓ РєСЂСѓР¶Р°Р»СЊС†СЏ Р»РёРјРѕРЅР°.
    8. Р—Р°РїС–РєР°Р№С‚Рµ 15вЂ“20 С…РІРёР»РёРЅ РґРѕ РІРЅСѓС‚СЂС–С€РЅСЊРѕС— С‚РµРјРїРµСЂР°С‚СѓСЂРё 63 В°C.
    9. Р”С–СЃС‚Р°РЅСЊС‚Рµ СЂРёР±Сѓ Р· РґСѓС…РѕРІРєРё С‚Р° Р·Р°Р»РёС€С‚Рµ РЅР° 3 С…РІРёР»РёРЅРё.
    10. РџРѕСЃРёРїС‚Рµ РїРѕРґСЂС–Р±РЅРµРЅРёРј РєСЂРѕРїРѕРј С– РїРѕРґР°РІР°Р№С‚Рµ С‚РµРїР»РѕСЋ.',
        '1. Preheat the oven to 190 В°C.
    2. Pat the salmon fillets dry with a paper towel and check for bones.
    3. Peel and finely mince the garlic.
    4. Wash the lemon. Squeeze the juice from one half and thinly slice the other half.
    5. Combine olive oil, lemon juice, garlic, salt and black pepper.
    6. Place the salmon skin-side down in a baking dish.
    7. Pour the marinade over the fish and arrange the lemon slices on top.
    8. Bake for 15вЂ“20 minutes until the internal temperature reaches 63 В°C.
    9. Remove from the oven and rest for 3 minutes.
    10. Sprinkle with chopped dill and serve warm.',
        '/images/recipes/baked-salmon.webp'
