    (
        'РџР»РѕРІ',
        'Rice pilaf with pork',
        'РЎРёС‚РЅРёР№ Р°СЂРѕРјР°С‚РЅРёР№ РїР»РѕРІ Р·С– СЃРІРёРЅРёРЅРѕСЋ, СЂРёСЃРѕРј, РјРѕСЂРєРІРѕСЋ, С‡Р°СЃРЅРёРєРѕРј С– СЃРїРµС†С–СЏРјРё.',
        'Hearty aromatic rice pilaf with pork, carrots, garlic and spices.',
        65, 610, 4,
        '1. РџСЂРѕРјРёР№С‚Рµ СЂРёСЃ РєС–Р»СЊРєР° СЂР°Р·С–РІ, РґРѕРєРё РІРѕРґР° РЅРµ СЃС‚Р°РЅРµ РјР°Р№Р¶Рµ РїСЂРѕР·РѕСЂРѕСЋ.
    2. РќР°СЂС–Р¶С‚Рµ СЃРІРёРЅРёРЅСѓ РєСѓР±РёРєР°РјРё СЂРѕР·РјС–СЂРѕРј РїСЂРёР±Р»РёР·РЅРѕ 3 СЃРј.
    3. РћС‡РёСЃС‚СЊС‚Рµ С†РёР±СѓР»СЋ С‚Р° РјРѕСЂРєРІСѓ. РќР°СЂС–Р¶С‚Рµ С†РёР±СѓР»СЋ РєСѓР±РёРєР°РјРё, Р° РјРѕСЂРєРІСѓ РґРѕРІРіРёРјРё СЃРјСѓР¶РєР°РјРё.
    4. Р РѕР·С–РіСЂС–Р№С‚Рµ СЃРѕРЅСЏС€РЅРёРєРѕРІСѓ РѕР»С–СЋ РІ РєР°Р·Р°РЅС– Р°Р±Рѕ РіР»РёР±РѕРєС–Р№ РєР°СЃС‚СЂСѓР»С–.
    5. РћР±СЃРјР°Р¶СѓР№С‚Рµ СЃРІРёРЅРёРЅСѓ РЅР° СЃРµСЂРµРґРЅСЊРѕ-СЃРёР»СЊРЅРѕРјСѓ РІРѕРіРЅС– 7вЂ“8 С…РІРёР»РёРЅ РґРѕ Р·РѕР»РѕС‚РёСЃС‚РѕС— СЃРєРѕСЂРёРЅРєРё.
    6. Р”РѕРґР°Р№С‚Рµ С†РёР±СѓР»СЋ С‚Р° РјРѕСЂРєРІСѓ. Р“РѕС‚СѓР№С‚Рµ С‰Рµ 5вЂ“7 С…РІРёР»РёРЅ.
    7. Р”РѕРґР°Р№С‚Рµ РєСѓРјРёРЅ, РїР°РїСЂРёРєСѓ, СЃС–Р»СЊ, С‡РѕСЂРЅРёР№ РїРµСЂРµС†СЊ С– РїРѕР»РѕРІРёРЅСѓ РІРѕРґРё. РўСѓС€РєСѓР№С‚Рµ 15 С…РІРёР»РёРЅ.
    8. Р’РёРєР»Р°РґС–С‚СЊ СЂРёСЃ СЂС–РІРЅРѕРјС–СЂРЅРёРј С€Р°СЂРѕРј РїРѕРІРµСЂС… РјвЂ™СЏСЃР° С‚Р° РѕРІРѕС‡С–РІ, РЅРµ РїРµСЂРµРјС–С€СѓСЋС‡Рё.
    9. Р”РѕРґР°Р№С‚Рµ РѕС‡РёС‰РµРЅС– Р·СѓР±С‡РёРєРё С‡Р°СЃРЅРёРєСѓ С‚Р° РѕР±РµСЂРµР¶РЅРѕ РІР»РёР№С‚Рµ СЂРµС€С‚Сѓ РіР°СЂСЏС‡РѕС— РІРѕРґРё.
    10. РќР°РєСЂРёР№С‚Рµ РєСЂРёС€РєРѕСЋ С‚Р° РіРѕС‚СѓР№С‚Рµ РЅР° СЃР»Р°Р±РєРѕРјСѓ РІРѕРіРЅС– 20вЂ“25 С…РІРёР»РёРЅ, РґРѕРєРё СЂРёСЃ РЅРµ РІР±РµСЂРµ РІРѕРґСѓ, Р° РјвЂ™СЏСЃРѕ РЅРµ СЃС‚Р°РЅРµ РіРѕС‚РѕРІРёРј.
    11. Р’РёРјРєРЅС–С‚СЊ РЅР°РіСЂС–РІР°РЅРЅСЏ С‚Р° Р·Р°Р»РёС€С‚Рµ РїР»РѕРІ РїС–Рґ РєСЂРёС€РєРѕСЋ РЅР° 10 С…РІРёР»РёРЅ.
    12. РћР±РµСЂРµР¶РЅРѕ РїРµСЂРµРјС–С€Р°Р№С‚Рµ С‚Р° РїРѕРґР°РІР°Р№С‚Рµ РіР°СЂСЏС‡РёРј.',
        '1. Rinse the rice several times until the water is nearly clear.
    2. Cut the pork into approximately 3 cm cubes.
    3. Peel the onion and carrots. Dice the onion and cut the carrots into long strips.
    4. Heat sunflower oil in a heavy-bottomed pot.
    5. Fry the pork over medium-high heat for 7вЂ“8 minutes until golden.
    6. Add the onion and carrots. Cook for another 5вЂ“7 minutes.
    7. Add cumin, paprika, salt, black pepper and half the water. Simmer for 15 minutes.
    8. Spread the rice evenly over the meat and vegetables without stirring.
    9. Add the peeled garlic cloves and carefully pour in the remaining hot water.
    10. Cover and cook over low heat for 20вЂ“25 minutes until the rice absorbs the water and the meat is cooked through.
    11. Turn off the heat and leave covered for 10 minutes.
    12. Stir gently and serve hot.',
        '/images/recipes/pilaf.webp'
