        'Sweet bell peppers filled with minced meat and rice, simmered in tomato sauce.',
        80, 440, 4,
        '1. РџСЂРѕРјРёР№С‚Рµ СЂРёСЃ РїС–Рґ РїСЂРѕС‚РѕС‡РЅРѕСЋ РІРѕРґРѕСЋ.
    2. Р—Р°Р»РёР№С‚Рµ СЂРёСЃ 200 РјР» РІРѕРґРё С‚Р° РІР°СЂС–С‚СЊ 8вЂ“10 С…РІРёР»РёРЅ РґРѕ РЅР°РїС–РІРіРѕС‚РѕРІРЅРѕСЃС‚С–. Р—Р°Р»РёС€С‚Рµ РѕС…РѕР»РѕРґР¶СѓРІР°С‚РёСЃСЏ.
    3. РџРѕРјРёР№С‚Рµ РїРµСЂРµС†СЊ, Р·СЂС–Р¶С‚Рµ РІРµСЂС…С–РІРєРё С‚Р° РІРёРґР°Р»С–С‚СЊ РЅР°СЃС–РЅРЅСЏ.
    4. РћС‡РёСЃС‚СЊС‚Рµ С†РёР±СѓР»СЋ, РјРѕСЂРєРІСѓ С‚Р° С‡Р°СЃРЅРёРє. Р¦РёР±СѓР»СЋ Р№ С‡Р°СЃРЅРёРє РїРѕРґСЂС–Р±РЅС–С‚СЊ, РјРѕСЂРєРІСѓ РЅР°С‚СЂС–С‚СЊ.
    5. Р РѕР·С–РіСЂС–Р№С‚Рµ РѕР»С–СЋ РЅР° РїР°С‚РµР»СЊРЅС– С‚Р° РѕР±СЃРјР°Р¶С‚Рµ С†РёР±СѓР»СЋ Р· РјРѕСЂРєРІРѕСЋ РїСЂРѕС‚СЏРіРѕРј 5 С…РІРёР»РёРЅ.
    6. Р—РјС–С€Р°Р№С‚Рµ С„Р°СЂС€, СЂРёСЃ, РїРѕР»РѕРІРёРЅСѓ РѕР±СЃРјР°Р¶РµРЅРёС… РѕРІРѕС‡С–РІ, С‡Р°СЃРЅРёРє, РїРѕР»РѕРІРёРЅСѓ СЃРѕР»С– С‚Р° С‡РѕСЂРЅРѕРіРѕ РїРµСЂС†СЋ.
    7. РќР°РїРѕРІРЅС–С‚СЊ РїРµСЂС†С– РЅР°С‡РёРЅРєРѕСЋ, Р·Р°Р»РёС€Р°СЋС‡Рё С‚СЂРѕС…Рё РІС–Р»СЊРЅРѕРіРѕ РјС–СЃС†СЏ РґР»СЏ СЂРёСЃСѓ.
    8. РџРѕСЃС‚Р°РІС‚Рµ С„Р°СЂС€РёСЂРѕРІР°РЅС– РїРµСЂС†С– РІРµСЂС‚РёРєР°Р»СЊРЅРѕ РІ РіР»РёР±РѕРєСѓ РєР°СЃС‚СЂСѓР»СЋ.
    9. Р—РјС–С€Р°Р№С‚Рµ СЂРµС€С‚Сѓ РѕР±СЃРјР°Р¶РµРЅРёС… РѕРІРѕС‡С–РІ, С‚РѕРјР°С‚РЅСѓ РїР°СЃС‚Сѓ, СЃРјРµС‚Р°РЅСѓ, СЂРµС€С‚Сѓ РІРѕРґРё, СЃРѕР»С– С‚Р° РїРµСЂС†СЋ.
    10. Р—Р°Р»РёР№С‚Рµ РїРµСЂС†С– СЃРѕСѓСЃРѕРј С– РґРѕРІРµРґС–С‚СЊ РґРѕ РєРёРїС–РЅРЅСЏ.
    11. РќР°РєСЂРёР№С‚Рµ РєСЂРёС€РєРѕСЋ С‚Р° С‚СѓС€РєСѓР№С‚Рµ РЅР° СЃР»Р°Р±РєРѕРјСѓ РІРѕРіРЅС– 40вЂ“45 С…РІРёР»РёРЅ РґРѕ РјвЂ™СЏРєРѕСЃС‚С– РїРµСЂС†СЋ С‚Р° РІРЅСѓС‚СЂС–С€РЅСЊРѕС— С‚РµРјРїРµСЂР°С‚СѓСЂРё РЅР°С‡РёРЅРєРё С‰РѕРЅР°Р№РјРµРЅС€Рµ 74 В°C.
    12. РџРѕСЃРёРїС‚Рµ РїРѕРґСЂС–Р±РЅРµРЅРѕСЋ РїРµС‚СЂСѓС€РєРѕСЋ С‚Р° РїРѕРґР°РІР°Р№С‚Рµ СЂР°Р·РѕРј С–Р· СЃРѕСѓСЃРѕРј.',
        '1. Rinse the rice under running water.
    2. Cover the rice with 200 ml of water and cook for 8вЂ“10 minutes until partially cooked. Allow to cool.
    3. Wash the bell peppers, cut off the tops and remove the seeds.
    4. Peel the onion, carrot and garlic. Chop the onion and garlic, and grate the carrot.
    5. Heat the oil in a frying pan and fry the onion and carrot for 5 minutes.
    6. Combine minced meat, rice, half the fried vegetables, garlic, half the salt and black pepper.
    7. Fill the peppers with the mixture, leaving a little room for the rice to expand.
    8. Arrange the stuffed peppers upright in a deep pot.
    9. Combine the remaining fried vegetables, tomato paste, sour cream, remaining water, salt and pepper.
    10. Pour the sauce over the peppers and bring to a boil.
    11. Cover and simmer over low heat for 40вЂ“45 minutes until the peppers are tender and the filling reaches at least 74 В°C.
    12. Sprinkle with chopped parsley and serve with the sauce.',
        '/images/recipes/stuffed-peppers.webp'
    ),
