        'Р—Р°РїРµС‡РµРЅРёР№ С…РµРє',
        'Baked hake with vegetables',
        'РќС–Р¶РЅРµ С„С–Р»Рµ С…РµРєР°, Р·Р°РїРµС‡РµРЅРµ Р· РєР°СЂС‚РѕРїР»РµСЋ, РјРѕСЂРєРІРѕСЋ, С†РёР±СѓР»РµСЋ С‚Р° Р»РёРјРѕРЅРѕРј.',
        'Tender hake fillets baked with potatoes, carrots, onion and lemon.',
        55, 370, 3,
        '1. Р РѕР·С–РіСЂС–Р№С‚Рµ РґСѓС…РѕРІРєСѓ РґРѕ 190 В°C.
