    3. РћР±СЃСѓС€С–С‚СЊ С„С–Р»Рµ С…РµРєР° РїР°РїРµСЂРѕРІРёРј СЂСѓС€РЅРёРєРѕРј С– РїРµСЂРµРІС–СЂС‚Рµ РЅР° РЅР°СЏРІРЅС–СЃС‚СЊ РєС–СЃС‚РѕРє.
