    5. РќР°СЂС–Р¶С‚Рµ РєР°СЂС‚РѕРїР»СЋ Р№ РјРѕСЂРєРІСѓ С‚РѕРЅРєРёРјРё РєСЂСѓР¶Р°Р»СЊС†СЏРјРё, Р° С†РёР±СѓР»СЋ РїС–РІРєС–Р»СЊС†СЏРјРё.
    6. Р—РјС–С€Р°Р№С‚Рµ РѕРІРѕС‡С– Р· РїРѕР»РѕРІРёРЅРѕСЋ РѕР»РёРІРєРѕРІРѕС— РѕР»С–С—, СЃРѕР»С– С‚Р° С‡РѕСЂРЅРѕРіРѕ РїРµСЂС†СЋ.
    7. Р’РёРєР»Р°РґС–С‚СЊ РѕРІРѕС‡С– Сѓ С„РѕСЂРјСѓ РґР»СЏ Р·Р°РїС–РєР°РЅРЅСЏ С‚Р° РіРѕС‚СѓР№С‚Рµ 20 С…РІРёР»РёРЅ.
    8. Р—РјС–С€Р°Р№С‚Рµ СЂРµС€С‚Сѓ РѕР»С–С—, Р»РёРјРѕРЅРЅРёР№ СЃС–Рє, РїР°РїСЂРёРєСѓ, СЃС–Р»СЊ С– С‡РѕСЂРЅРёР№ РїРµСЂРµС†СЊ.
    9. Р—РјР°СЃС‚С–С‚СЊ СЂРёР±Сѓ РѕС‚СЂРёРјР°РЅРѕСЋ СЃСѓРјС–С€С€СЋ С‚Р° РІРёРєР»Р°РґС–С‚СЊ РїРѕРІРµСЂС… РѕРІРѕС‡С–РІ.
    10. Р—Р°РїС–РєР°Р№С‚Рµ С‰Рµ 15вЂ“20 С…РІРёР»РёРЅ РґРѕ РјвЂ™СЏРєРѕСЃС‚С– РѕРІРѕС‡С–РІ С‚Р° РІРЅСѓС‚СЂС–С€РЅСЊРѕС— С‚РµРјРїРµСЂР°С‚СѓСЂРё СЂРёР±Рё 63 В°C.
    11. РџРѕСЃРёРїС‚Рµ РїРѕРґСЂС–Р±РЅРµРЅРёРј РєСЂРѕРїРѕРј С– РїРѕРґР°РІР°Р№С‚Рµ РіР°СЂСЏС‡РёРј.',
        '1. Preheat the oven to 190 В°C.
    2. If the fish is frozen, thaw it in the refrigerator beforehand.
    3. Pat the hake fillets dry and check for bones.
    4. Peel the potatoes, carrots and onion.
    5. Thinly slice the potatoes and carrots, and cut the onion into half-rings.
    6. Toss the vegetables with half the olive oil, salt and black pepper.
    7. Place the vegetables in a baking dish and bake for 20 minutes.
    8. Combine the remaining oil, lemon juice, paprika, salt and black pepper.
    9. Coat the fish with the mixture and place it on top of the vegetables.
    10. Bake for another 15вЂ“20 minutes until the vegetables are tender and the fish reaches an internal temperature of 63 В°C.
    11. Sprinkle with chopped dill and serve hot.',
        '/images/recipes/baked-hake.webp'
    )
