    11. Р’РёРїС–РєР°Р№С‚Рµ 10вЂ“15 С…РІРёР»РёРЅ РґРѕ Р·РѕР»РѕС‚РёСЃС‚РёС… РєСЂР°С—РІ С– СЂРѕР·РїР»Р°РІР»РµРЅРЅСЏ СЃРёСЂСѓ.
    12. РџСЂРёРєСЂР°СЃСЊС‚Рµ СЃРІС–Р¶РёРј Р±Р°Р·РёР»С–РєРѕРј, РЅР°СЂС–Р¶С‚Рµ С‚Р° РїРѕРґР°РІР°Р№С‚Рµ РіР°СЂСЏС‡РѕСЋ.',
        '1. Warm the water to 35вЂ“38 В°C.
