    7. РћС‡РёСЃС‚СЊС‚Рµ РїРµС‡РµСЂРёС†С– С‚Р° РЅР°СЂС–Р¶С‚Рµ С‚РѕРЅРєРёРјРё РїР»Р°СЃС‚РёРЅРєР°РјРё. РћР±СЃРјР°Р¶С‚Рµ С—С… РЅР° СЃСѓС…С–Р№ РїР°С‚РµР»СЊРЅС– 5вЂ“7 С…РІРёР»РёРЅ РґРѕ РІРёРїР°СЂРѕРІСѓРІР°РЅРЅСЏ Р·Р°Р№РІРѕС— СЂС–РґРёРЅРё.
