    11. Р—РјР°СЃС‚С–С‚СЊ РѕСЃРЅРѕРІСѓ С‚РѕРјР°С‚РЅРёРј СЃРѕСѓСЃРѕРј, СЂРѕР·РїРѕРґС–Р»С–С‚СЊ РјРѕС†Р°СЂРµР»Сѓ, С€РёРЅРєСѓ С‚Р° РіСЂРёР±Рё.
    12. Р’РёРїС–РєР°Р№С‚Рµ 12вЂ“15 С…РІРёР»РёРЅ РґРѕ Р·РѕР»РѕС‚РёСЃС‚РѕС— СЃРєРѕСЂРёРЅРєРё С‚Р° СЂРѕР·РїР»Р°РІР»РµРЅРЅСЏ СЃРёСЂСѓ.',
        '1. Warm the water to 35вЂ“38 В°C, add dry yeast and sugar. Leave for 10 minutes.
    2. Sift the flour and add half the salt, yeast mixture and half the olive oil.
    3. Knead for 8вЂ“10 minutes until the dough is smooth and elastic.
    4. Cover the dough and leave in a warm place for 45вЂ“60 minutes.
    5. Wash the tomatoes and chop them together with the garlic.
    6. Heat the remaining oil in a frying pan. Add tomatoes, garlic, tomato paste, oregano, remaining salt and black pepper. Simmer for 10вЂ“15 minutes.
    7. Clean the mushrooms and slice them thinly. Fry in a dry pan for 5вЂ“7 minutes until excess moisture evaporates.
    8. Cut the ham into thin strips and the mozzarella into small pieces.
    9. Preheat the oven to 230 В°C.
    10. Stretch the dough into a round base approximately 30 cm wide and place it on baking parchment.
    11. Spread the tomato sauce over the base and distribute the mozzarella, ham and mushrooms.
    12. Bake for 12вЂ“15 minutes until the crust is golden and the cheese has melted.',
