        'Creamy cheesecake with a crunchy biscuit base, topped with fresh strawberries.',
        420, 490, 8,
        '1. Р”С–СЃС‚Р°РЅСЊС‚Рµ РІРµСЂС€РєРѕРІРёР№ СЃРёСЂ, СЏР№С†СЏ С‚Р° РІРµСЂС€РєРё Р· С…РѕР»РѕРґРёР»СЊРЅРёРєР° Р·Р° 30 С…РІРёР»РёРЅ РґРѕ РїСЂРёРіРѕС‚СѓРІР°РЅРЅСЏ.
    2. Р РѕР·С–РіСЂС–Р№С‚Рµ РґСѓС…РѕРІРєСѓ РґРѕ 170 В°C. Р—Р°СЃС‚РµР»С–С‚СЊ РґРЅРѕ СЂРѕР·''С”РјРЅРѕС— С„РѕСЂРјРё РґС–Р°РјРµС‚СЂРѕРј 20 СЃРј РїРµСЂРіР°РјРµРЅС‚РѕРј.
    3. РџРѕРґСЂС–Р±РЅС–С‚СЊ РїРµС‡РёРІРѕ Р±Р»РµРЅРґРµСЂРѕРј РґРѕ РґСЂС–Р±РЅРѕС— РєСЂРёС…С‚Рё.
    4. Р РѕР·С‚РѕРїС–С‚СЊ РІРµСЂС€РєРѕРІРµ РјР°СЃР»Рѕ С‚Р° Р·РјС–С€Р°Р№С‚Рµ Р№РѕРіРѕ Р· РєСЂРёС…С‚РѕСЋ РїРµС‡РёРІР°.
    5. Р’РёРєР»Р°РґС–С‚СЊ СЃСѓРјС–С€ РЅР° РґРЅРѕ С„РѕСЂРјРё, С‰С–Р»СЊРЅРѕ СѓС‚СЂР°РјР±СѓР№С‚Рµ С‚Р° РІРёРїС–РєР°Р№С‚Рµ 10 С…РІРёР»РёРЅ. Р—Р°Р»РёС€С‚Рµ РѕС…РѕР»РѕРґР¶СѓРІР°С‚РёСЃСЏ.
    6. Р—РјРµРЅС€С‚Рµ С‚РµРјРїРµСЂР°С‚СѓСЂСѓ РґСѓС…РѕРІРєРё РґРѕ 150 В°C.
    7. Р—РјС–С€Р°Р№С‚Рµ РІРµСЂС€РєРѕРІРёР№ СЃРёСЂ С–Р· С†СѓРєСЂРѕРј С‚Р° РІР°РЅС–Р»СЊРЅРёРј С†СѓРєСЂРѕРј РґРѕ РѕРґРЅРѕСЂС–РґРЅРѕСЃС‚С–.
    8. РџРѕ РѕРґРЅРѕРјСѓ РґРѕРґР°Р№С‚Рµ СЏР№С†СЏ, РѕР±РµСЂРµР¶РЅРѕ РїРµСЂРµРјС–С€СѓСЋС‡Рё РїС–СЃР»СЏ РєРѕР¶РЅРѕРіРѕ. Р’Р»РёР№С‚Рµ РІРµСЂС€РєРё, РґРѕРґР°Р№С‚Рµ РєСЂРѕС…РјР°Р»СЊ С– Р»РёРјРѕРЅРЅРёР№ СЃС–Рє.
    9. Р’РёР»РёР№С‚Рµ СЃРёСЂРЅСѓ РјР°СЃСѓ РЅР° РѕСЃРЅРѕРІСѓ С‚Р° Р·Р»РµРіРєР° РїРѕСЃС‚СѓРєР°Р№С‚Рµ С„РѕСЂРјРѕСЋ РѕР± СЃС‚С–Р», С‰РѕР± РІРёРґР°Р»РёС‚Рё РІРµР»РёРєС– Р±СѓР»СЊР±Р°С€РєРё РїРѕРІС–С‚СЂСЏ.
    10. Р’РёРїС–РєР°Р№С‚Рµ 60вЂ“75 С…РІРёР»РёРЅ. РљСЂР°С— РјР°СЋС‚СЊ Р·Р°СЃС‚РёРіРЅСѓС‚Рё, Р° СЃРµСЂРµРґРёРЅР° Р·Р°Р»РёС€Р°С‚РёСЃСЏ С‚СЂРѕС…Рё СЂСѓС…РѕРјРѕСЋ.
    11. Р’РёРјРєРЅС–С‚СЊ РґСѓС…РѕРІРєСѓ, РїСЂРѕС‡РёРЅС–С‚СЊ РґРІРµСЂС†СЏС‚Р° С‚Р° Р·Р°Р»РёС€С‚Рµ С‡С–Р·РєРµР№Рє СѓСЃРµСЂРµРґРёРЅС– РЅР° 30 С…РІРёР»РёРЅ. РћС…РѕР»РѕРґС–С‚СЊ РґРѕ РєС–РјРЅР°С‚РЅРѕС— С‚РµРјРїРµСЂР°С‚СѓСЂРё С‚Р° РїРѕСЃС‚Р°РІС‚Рµ РІ С…РѕР»РѕРґРёР»СЊРЅРёРє С‰РѕРЅР°Р№РјРµРЅС€Рµ РЅР° 4 РіРѕРґРёРЅРё.
    12. РџРѕРјРёР№С‚Рµ Р№ РѕР±СЃСѓС€С–С‚СЊ РїРѕР»СѓРЅРёС†СЋ. РџСЂРёРєСЂР°СЃСЊС‚Рµ РѕС…РѕР»РѕРґР¶РµРЅРёР№ С‡С–Р·РєРµР№Рє СЏРіРѕРґР°РјРё С‚Р° РЅР°СЂС–Р¶С‚Рµ РїРѕСЂС†С–Р№РЅРёРјРё С€РјР°С‚РѕС‡РєР°РјРё.',
        '1. Remove the cream cheese, eggs and cream from the refrigerator 30 minutes before cooking.
    2. Preheat the oven to 170 В°C. Line the bottom of a 20 cm springform pan with baking parchment.
    3. Crush the biscuits in a blender until fine crumbs form.
    4. Melt the butter and combine it with the biscuit crumbs.
    5. Press the mixture firmly into the bottom of the pan and bake for 10 minutes. Allow to cool.
    6. Reduce the oven temperature to 150 В°C.
    7. Mix the cream cheese with sugar and vanilla sugar until smooth.
    8. Add the eggs one at a time, mixing gently after each addition. Add cream, starch and lemon juice.
    9. Pour the filling over the base and gently tap the pan against the counter to remove large air bubbles.
    10. Bake for 60вЂ“75 minutes. The edges should be set while the centre remains slightly wobbly.
    11. Turn off the oven, open the door slightly and leave the cheesecake inside for 30 minutes. Cool to room temperature and refrigerate for at least 4 hours.
    12. Wash and dry the strawberries. Decorate the chilled cheesecake with berries and slice into portions.',
        '/images/recipes/cheesecake.webp'
