    (
        'РЁРѕРєРѕР»Р°РґРЅРёР№ С‚РѕСЂС‚',
        'Chocolate cake',
        'РќР°СЃРёС‡РµРЅРёР№ С€РѕРєРѕР»Р°РґРЅРёР№ С‚РѕСЂС‚ С–Р· РјвЂ™СЏРєРёРјРё Р±С–СЃРєРІС–С‚РЅРёРјРё РєРѕСЂР¶Р°РјРё С‚Р° РЅС–Р¶РЅРёРј С€РѕРєРѕР»Р°РґРЅРёРј РєСЂРµРјРѕРј.',
        'Rich chocolate cake with soft sponge layers and smooth chocolate ganache.',
        150, 540, 10,
        '1. Р РѕР·С–РіСЂС–Р№С‚Рµ РґСѓС…РѕРІРєСѓ РґРѕ 175 В°C. Р—Р°СЃС‚РµР»С–С‚СЊ РґРЅРѕ С„РѕСЂРјРё РґС–Р°РјРµС‚СЂРѕРј 20 СЃРј РїРµСЂРіР°РјРµРЅС‚РѕРј.
    2. РџСЂРѕСЃС–Р№С‚Рµ Р±РѕСЂРѕС€РЅРѕ, РєР°РєР°Рѕ, СЂРѕР·РїСѓС€СѓРІР°С‡ С– С…Р°СЂС‡РѕРІСѓ СЃРѕРґСѓ. Р”РѕРґР°Р№С‚Рµ СЃС–Р»СЊ.
    3. Р’ РѕРєСЂРµРјС–Р№ РјРёСЃС†С– Р·Р±РёР№С‚Рµ СЏР№С†СЏ С–Р· С†СѓРєСЂРѕРј С‚Р° РІР°РЅС–Р»СЊРЅРёРј С†СѓРєСЂРѕРј РїСЂРѕС‚СЏРіРѕРј 3вЂ“4 С…РІРёР»РёРЅ.
    4. Р”РѕРґР°Р№С‚Рµ РјРѕР»РѕРєРѕ С‚Р° СЃРѕРЅСЏС€РЅРёРєРѕРІСѓ РѕР»С–СЋ, РїРµСЂРµРјС–С€Р°Р№С‚Рµ РґРѕ РѕРґРЅРѕСЂС–РґРЅРѕСЃС‚С–.
    5. РџРѕСЃС‚СѓРїРѕРІРѕ РґРѕРґР°Р№С‚Рµ СЃСѓС…С– С–РЅРіСЂРµРґС–С”РЅС‚Рё С‚Р° РїРµСЂРµРјС–С€Р°Р№С‚Рµ РІС–РЅС‡РёРєРѕРј.
    6. Р’Р»РёР№С‚Рµ РіР°СЂСЏС‡Сѓ РІРѕРґСѓ Р№ РѕР±РµСЂРµР¶РЅРѕ РїРµСЂРµРјС–С€Р°Р№С‚Рµ. РўС–СЃС‚Рѕ РјР°С” Р±СѓС‚Рё РґРѕСЃРёС‚СЊ СЂС–РґРєРёРј.
    7. РџРµСЂРµР»РёР№С‚Рµ С‚С–СЃС‚Рѕ Сѓ С„РѕСЂРјСѓ С‚Р° РІРёРїС–РєР°Р№С‚Рµ 40вЂ“50 С…РІРёР»РёРЅ. РџРµСЂРµРІС–СЂС‚Рµ РіРѕС‚РѕРІРЅС–СЃС‚СЊ РґРµСЂРµРІвЂ™СЏРЅРѕСЋ С€РїР°Р¶РєРѕСЋ.
    8. Р—Р°Р»РёС€С‚Рµ Р±С–СЃРєРІС–С‚ Сѓ С„РѕСЂРјС– РЅР° 10 С…РІРёР»РёРЅ, РїРѕС‚С–Рј РїРµСЂРµРєР»Р°РґС–С‚СЊ РЅР° СЂРµС€С–С‚РєСѓ С‚Р° РїРѕРІРЅС–СЃС‚СЋ РѕС…РѕР»РѕРґС–С‚СЊ.
    9. РџРѕРґСЂС–Р±РЅС–С‚СЊ С€РѕРєРѕР»Р°Рґ. РќР°РіСЂС–Р№С‚Рµ РІРµСЂС€РєРё РјР°Р№Р¶Рµ РґРѕ РєРёРїС–РЅРЅСЏ С‚Р° Р·Р°Р»РёР№С‚Рµ РЅРёРјРё С€РѕРєРѕР»Р°Рґ.
    10. Р—Р°Р»РёС€С‚Рµ РЅР° 2 С…РІРёР»РёРЅРё, РїРµСЂРµРјС–С€Р°Р№С‚Рµ РґРѕ РіР»Р°РґРєРѕС— РєРѕРЅСЃРёСЃС‚РµРЅС†С–С— С‚Р° РѕС…РѕР»РѕРґС–С‚СЊ РґРѕ Р·Р°РіСѓСЃС‚С–РЅРЅСЏ.
    11. Р РѕР·СЂС–Р¶С‚Рµ Р±С–СЃРєРІС–С‚ РіРѕСЂРёР·РѕРЅС‚Р°Р»СЊРЅРѕ РЅР° РґРІР° РєРѕСЂР¶С–. Р—РјР°СЃС‚С–С‚СЊ РЅРёР¶РЅС–Р№ РєРѕСЂР¶ С‡Р°СЃС‚РёРЅРѕСЋ С€РѕРєРѕР»Р°РґРЅРѕРіРѕ РєСЂРµРјСѓ.
    12. РќР°РєСЂРёР№С‚Рµ РґСЂСѓРіРёРј РєРѕСЂР¶РµРј, РїРѕРєСЂРёР№С‚Рµ РІРµСЂС… С– Р±РѕРєРё СЂРµС€С‚РѕСЋ РєСЂРµРјСѓ С‚Р° РїРѕСЃС‚Р°РІС‚Рµ РІ С…РѕР»РѕРґРёР»СЊРЅРёРє РЅР° 30 С…РІРёР»РёРЅ.',
        '1. Preheat the oven to 175 В°C. Line the bottom of a 20 cm cake pan with baking parchment.
    2. Sift together flour, cocoa powder, baking powder and baking soda. Add salt.
    3. In a separate bowl, beat the eggs with sugar and vanilla sugar for 3вЂ“4 minutes.
    4. Add milk and sunflower oil and mix until smooth.
    5. Gradually add the dry ingredients and whisk until combined.
    6. Pour in the hot water and mix gently. The batter should be fairly thin.
    7. Pour the batter into the pan and bake for 40вЂ“50 minutes. Check doneness with a wooden skewer.
    8. Leave the sponge in the pan for 10 minutes, then transfer to a wire rack and cool completely.
    9. Chop the chocolate. Heat the cream until almost boiling and pour it over the chocolate.
    10. Leave for 2 minutes, stir until smooth and cool until thickened.
    11. Slice the sponge horizontally into two layers. Spread some chocolate ganache over the bottom layer.
    12. Cover with the second layer, coat the top and sides with the remaining ganache and refrigerate for 30 minutes.',
