    FROM (VALUES
    (
        'Р‘СЂСѓСЃРєРµС‚Рё Р· РїРѕРјС–РґРѕСЂР°РјРё',
        'Tomato bruschetta',
        'РҐСЂСѓСЃС‚РєС– СЃРєРёР±РѕС‡РєРё Р±Р°РіРµС‚Р° Р·С– СЃРІС–Р¶РёРјРё РїРѕРјС–РґРѕСЂР°РјРё, С‡Р°СЃРЅРёРєРѕРј, Р±Р°Р·РёР»С–РєРѕРј С‚Р° РѕР»РёРІРєРѕРІРѕСЋ РѕР»С–С”СЋ.',
        'Crispy baguette slices topped with fresh tomatoes, garlic, basil and olive oil.',
        20, 260, 3,
        '1. Р РѕР·С–РіСЂС–Р№С‚Рµ РґСѓС…РѕРІРєСѓ РґРѕ 200 В°C.
    2. РќР°СЂС–Р¶С‚Рµ Р±Р°РіРµС‚ СЃРєРёР±РѕС‡РєР°РјРё Р·Р°РІС‚РѕРІС€РєРё РїСЂРёР±Р»РёР·РЅРѕ 1,5вЂ“2 СЃРј.
    3. Р’РёРєР»Р°РґС–С‚СЊ СЃРєРёР±РѕС‡РєРё РЅР° РґРµРєРѕ С‚Р° Р·РјР°СЃС‚С–С‚СЊ РїРѕР»РѕРІРёРЅРѕСЋ РѕР»РёРІРєРѕРІРѕС— РѕР»С–С—.
    4. Р—Р°РїС–РєР°Р№С‚Рµ 5вЂ“7 С…РІРёР»РёРЅ РґРѕ Р·РѕР»РѕС‚РёСЃС‚РѕС— С…СЂСѓСЃС‚РєРѕС— СЃРєРѕСЂРёРЅРєРё.
    5. РџРѕРјРёР№С‚Рµ РїРѕРјС–РґРѕСЂРё, РІРёРґР°Р»С–С‚СЊ С‚РІРµСЂРґС– С‡Р°СЃС‚РёРЅРё С‚Р° РЅР°СЂС–Р¶С‚Рµ РјвЂ™СЏРєРѕС‚СЊ РЅРµРІРµР»РёРєРёРјРё РєСѓР±РёРєР°РјРё.
    6. РџРѕРјРёР№С‚Рµ Р±Р°Р·РёР»С–Рє, РѕР±СЃСѓС€С–С‚СЊ С– РґСЂС–Р±РЅРѕ РЅР°СЂС–Р¶С‚Рµ.
    7. РћС‡РёСЃС‚СЊС‚Рµ С‡Р°СЃРЅРёРє. РћРґРёРЅ Р·СѓР±С‡РёРє РїРѕРґСЂС–Р±РЅС–С‚СЊ, Р° РґСЂСѓРіРёРј РЅР°С‚СЂС–С‚СЊ С‚РµРїР»С– СЃРєРёР±РѕС‡РєРё Р±Р°РіРµС‚Р°.
    8. Р—РјС–С€Р°Р№С‚Рµ РїРѕРјС–РґРѕСЂРё, РїРѕРґСЂС–Р±РЅРµРЅРёР№ С‡Р°СЃРЅРёРє, Р±Р°Р·РёР»С–Рє, СЂРµС€С‚Сѓ РѕР»РёРІРєРѕРІРѕС— РѕР»С–С—, СЃС–Р»СЊ С– С‡РѕСЂРЅРёР№ РїРµСЂРµС†СЊ.
    9. Р—Р°Р»РёС€С‚Рµ РЅР°С‡РёРЅРєСѓ РЅР° 5 С…РІРёР»РёРЅ, С‰РѕР± РїРѕС”РґРЅР°Р»РёСЃСЏ Р°СЂРѕРјР°С‚Рё.
    10. Р’РёРєР»Р°РґС–С‚СЊ РїРѕРјС–РґРѕСЂРѕРІСѓ СЃСѓРјС–С€ РЅР° РїС–РґСЃРјР°Р¶РµРЅРёР№ Р±Р°РіРµС‚ Р±РµР·РїРѕСЃРµСЂРµРґРЅСЊРѕ РїРµСЂРµРґ РїРѕРґР°РІР°РЅРЅСЏРј.',
        '1. Preheat the oven to 200 В°C.
    2. Cut the baguette into slices approximately 1.5вЂ“2 cm thick.
    3. Arrange the slices on a baking tray and brush with half the olive oil.
    4. Bake for 5вЂ“7 minutes until golden and crispy.
    5. Wash the tomatoes, remove the tough cores and dice the flesh.
    6. Wash, dry and finely chop the basil.
    7. Peel the garlic. Mince one clove and rub the warm baguette slices with the other.
