        '1. РћС‡РёСЃС‚СЊС‚Рµ СЃС‚РёРіР»С– Р±Р°РЅР°РЅРё С‚Р° РЅР°СЂС–Р¶С‚Рµ РЅРµРІРµР»РёРєРёРјРё РєСЂСѓР¶Р°Р»СЊС†СЏРјРё.
    2. Р’С–РґРјС–СЂСЏР№С‚Рµ РЅРµРѕР±С…С–РґРЅСѓ РєС–Р»СЊРєС–СЃС‚СЊ РІС–РІСЃСЏРЅРєРё С‚Р° РїРµСЂРµРєР»Р°РґС–С‚СЊ С—С— РІ С‡Р°С€Сѓ Р±Р»РµРЅРґРµСЂР°.
    3. Р”РѕРґР°Р№С‚Рµ РїРѕР»РѕРІРёРЅСѓ РјРѕР»РѕРєР° С‚Р° Р·Р°Р»РёС€С‚Рµ РЅР° 5 С…РІРёР»РёРЅ, С‰РѕР± РІС–РІСЃСЏРЅРєР° С‚СЂРѕС…Рё СЂРѕР·РјвЂ™СЏРєР»Р°.
    4. Р”РѕРґР°Р№С‚Рµ РЅР°СЂС–Р·Р°РЅС– Р±Р°РЅР°РЅРё, РјРµРґ С– СЂРµС€С‚Сѓ РјРѕР»РѕРєР°.
    5. Р—Р±РёРІР°Р№С‚Рµ РЅР° РІРёСЃРѕРєС–Р№ С€РІРёРґРєРѕСЃС‚С– РїСЂРѕС‚СЏРіРѕРј 1вЂ“2 С…РІРёР»РёРЅ РґРѕ РѕРґРЅРѕСЂС–РґРЅРѕС— РєСЂРµРјРѕРІРѕС— РєРѕРЅСЃРёСЃС‚РµРЅС†С–С—.
    6. Р”РѕРґР°Р№С‚Рµ Р±С–Р»СЊС€Сѓ С‡Р°СЃС‚РёРЅСѓ РєРѕСЂРёС†С– С‚Р° Р·Р±РёРІР°Р№С‚Рµ С‰Рµ 10 СЃРµРєСѓРЅРґ.
    7. Р РѕР·Р»РёР№С‚Рµ СЃРјСѓР·С– Сѓ РґРІС– СЃРєР»СЏРЅРєРё.
