    6. Add most of the cinnamon and blend for another 10 seconds.
    7. Pour the smoothie into two glasses.
    8. Sprinkle with the remaining cinnamon and serve immediately.',
        '/images/recipes/banana-smoothie.webp'
    ),
    (
        'РџРѕР»СѓРЅРёС‡РЅРёР№ РјРѕР»РѕС‡РЅРёР№ РєРѕРєС‚РµР№Р»СЊ',
        'Strawberry milkshake',
        'РћСЃРІС–Р¶Р°СЋС‡РёР№ РјРѕР»РѕС‡РЅРёР№ РєРѕРєС‚РµР№Р»СЊ Р·С– СЃРІС–Р¶РѕСЋ РїРѕР»СѓРЅРёС†РµСЋ, РІРµСЂС€РєРѕРІРёРј РјРѕСЂРѕР·РёРІРѕРј С‚Р° РІР°РЅС–Р»СЊРЅРёРј Р°СЂРѕРјР°С‚РѕРј.',
        'Refreshing milkshake with fresh strawberries, creamy ice cream and vanilla flavour.',
        10, 310, 2,
        '1. Р РµС‚РµР»СЊРЅРѕ РїРѕРјРёР№С‚Рµ РїРѕР»СѓРЅРёС†СЋ РїС–Рґ РїСЂРѕС…РѕР»РѕРґРЅРѕСЋ РїСЂРѕС‚РѕС‡РЅРѕСЋ РІРѕРґРѕСЋ.
    2. Р’РёРґР°Р»С–С‚СЊ Р·РµР»РµРЅС– РїР»РѕРґРѕРЅС–Р¶РєРё С‚Р° СЂРѕР·СЂС–Р¶С‚Рµ РІРµР»РёРєС– СЏРіРѕРґРё РЅР°РІРїС–Р».
    3. Р’С–РґРєР»Р°РґС–С‚СЊ РґРІС– СЏРіРѕРґРё РґР»СЏ РїСЂРёРєСЂР°С€Р°РЅРЅСЏ РіРѕС‚РѕРІРѕРіРѕ РЅР°РїРѕСЋ.
    4. РџРµСЂРµРєР»Р°РґС–С‚СЊ СЂРµС€С‚Сѓ РїРѕР»СѓРЅРёС†С– РІ С‡Р°С€Сѓ Р±Р»РµРЅРґРµСЂР°.
    5. Р”РѕРґР°Р№С‚Рµ РѕС…РѕР»РѕРґР¶РµРЅРµ РјРѕР»РѕРєРѕ, РІРµСЂС€РєРѕРІРµ РјРѕСЂРѕР·РёРІРѕ С‚Р° РІР°РЅС–Р»СЊРЅРёР№ С†СѓРєРѕСЂ.
    6. Р—Р±РёРІР°Р№С‚Рµ РїСЂРѕС‚СЏРіРѕРј 45вЂ“60 СЃРµРєСѓРЅРґ РґРѕ РѕРґРЅРѕСЂС–РґРЅРѕС— РєРѕРЅСЃРёСЃС‚РµРЅС†С–С— С‚Р° СѓС‚РІРѕСЂРµРЅРЅСЏ Р»РµРіРєРѕС— РїС–РЅРё.
    7. Р РѕР·Р»РёР№С‚Рµ РєРѕРєС‚РµР№Р»СЊ Сѓ РґРІС– РІРёСЃРѕРєС– СЃРєР»СЏРЅРєРё.
    8. РџСЂРёРєСЂР°СЃСЊС‚Рµ РєРѕР¶РЅСѓ СЃРєР»СЏРЅРєСѓ РїРѕР»СѓРЅРёС†РµСЋ С‚Р° РїРѕРґР°РІР°Р№С‚Рµ РѕРґСЂР°Р·Сѓ, РїРѕРєРё РєРѕРєС‚РµР№Р»СЊ С…РѕР»РѕРґРЅРёР№.',
        '1. Thoroughly wash the strawberries under cool running water.
    2. Remove the green stems and cut large berries in half.
    3. Reserve two strawberries for garnishing the finished drink.
    4. Transfer the remaining strawberries to a blender.
    5. Add chilled milk, creamy ice cream and vanilla sugar.
    6. Blend for 45вЂ“60 seconds until smooth and slightly frothy.
    7. Pour the milkshake into two tall glasses.
    8. Garnish each glass with a strawberry and serve immediately while cold.',
        '/images/recipes/strawberry-milkshake.webp'
    ),
    (
        'Р”РѕРјР°С€РЅС–Р№ Р»РёРјРѕРЅР°Рґ',
        'Homemade lemonade',
        'РћСЃРІС–Р¶Р°СЋС‡РёР№ РґРѕРјР°С€РЅС–Р№ РЅР°РїС–Р№ С–Р· РЅР°С‚СѓСЂР°Р»СЊРЅРёРј Р»РёРјРѕРЅРЅРёРј СЃРѕРєРѕРј, СЃРІС–Р¶РѕСЋ РјвЂ™СЏС‚РѕСЋ С‚Р° Р»РµРіРєРѕСЋ СЃРѕР»РѕРґРєС–СЃС‚СЋ.',
        'Refreshing homemade drink with natural lemon juice, fresh mint and a touch of sweetness.',
        40, 80, 4,
        '1. Р РµС‚РµР»СЊРЅРѕ РїРѕРјРёР№С‚Рµ Р»РёРјРѕРЅРё С‚Р° Р»РёСЃС‚СЏ РјвЂ™СЏС‚Рё.
